INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('90c98056-68be-46be-aa04-d50b31acd8bb', 'data-science', 'Data Science', NULL, 'Build comprehensive Data Science skills through Python programming, mathematics and statistics, SQL, Pandas, data cleaning, visualization, exploratory data analysis, machine learning, model evaluation, feature engineering, deep learning, NLP, time series analysis, big data, cloud technologies, Git, APIs, deployment, and interactive data applications.', '["Python Programming, Statistics, SQL & Data Analysis","Pandas, Data Visualization, EDA & Feature Engineering","Machine Learning, Model Evaluation & Deep Learning","NLP, Time Series, Big Data, Cloud & Deployment"]'::jsonb, 'https://marvelslice.com/uploads/1789565119858_nqgq3bf233.jpg', NULL, NULL, 'd02fba7a-68da-49cb-b9d1-1284fbe71a4c', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T13:25:27.447729+00:00', false, 'Build Your Career in Data Science', 'Learn Python, SQL, statistics, data analysis, visualization, machine learning, deep learning, NLP, time series, cloud, deployment, and data science tools through a structured learning pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789565048709_cpwzgfanhk.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('d4b389f5-3cd1-4008-955f-9c5898d93f04', 'generative-ai', 'Generative AI', NULL, 'Build practical Generative AI skills from Artificial Intelligence fundamentals and Python through foundation models, large language models, Transformers, prompt engineering, LLM APIs, embeddings, Retrieval-Augmented Generation, vector databases, LangChain, AI agents, application development, deployment, Git, and responsible AI security.', '["AI Fundamentals, Python & Mathematics for AI","Generative AI, LLMs, Transformers & Prompt Engineering","LLM APIs, RAG, Embeddings, Vector Databases & LangChain","AI Agents, Application Development, Deployment & Security"]'::jsonb, 'https://marvelslice.com/uploads/1789565620093_xhwvasx5kl.jpg', NULL, NULL, 'd02fba7a-68da-49cb-b9d1-1284fbe71a4c', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T13:33:50.793841+00:00', false, 'Build Intelligent Applications with Generative AI', 'Learn Generative AI, LLMs, prompt engineering, RAG, vector databases, LangChain, AI agents, APIs, application development, deployment, and AI security through a structured learning pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789565306976_uv6pummtglj.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('34d0272e-3a86-455e-93a5-f5d254e5f388', 'python-developer', 'Python Developer', NULL, 'Build a strong foundation in Python development and progress toward professional application development through programming fundamentals, Core Python, object-oriented programming, advanced Python, MySQL, database connectivity, Flask or Django, REST APIs, Git and GitHub, testing, automation, and deployment. Develop practical skills for creating database-driven applications, APIs, automation tools, and web applications.', '["Python Programming, Core Python & Object-Oriented Programming","Advanced Python, MySQL & Database Connectivity","Flask/Django, REST APIs & Web Application Development","Automation, Testing, Git, Docker & Deployment"]'::jsonb, 'https://marvelslice.com/uploads/1789563668560_7ukb1u6f6ar.jpg', NULL, NULL, 'bc18c759-26c3-4513-89c0-4a96f36f4b48', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T13:01:45.313174+00:00', false, 'Build Your Career as a Python Developer', 'Learn Python, OOP, MySQL, Flask or Django, REST APIs, automation, testing, Git, Docker, and deployment through a structured Python development pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789563680652_8veztux7g0a.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('77103a8b-5d86-4b71-8e8d-fe74ca961b77', 'nodejs-development', 'Node.js Development', NULL, 'Build comprehensive backend development skills with Node.js and JavaScript. Learn Node.js architecture, asynchronous programming, core modules, npm, HTTP servers, Express.js, REST APIs, MongoDB, Mongoose, authentication, file uploads, WebSockets, Socket.IO, security, testing, debugging, logging, deployment, Docker, performance optimization, Redis, and GraphQL.', '["Node.js, JavaScript, npm & Core Modules","Asynchronous Programming, HTTP Servers & Express.js","REST APIs, MongoDB, Authentication & File Uploads","Real-Time Applications, Security, Testing & Deployment"]'::jsonb, 'https://marvelslice.com/uploads/1789565939438_4dl59y76tk.jpg', NULL, NULL, 'bc18c759-26c3-4513-89c0-4a96f36f4b48', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T13:39:09.266625+00:00', false, 'Build Powerful Backend Applications with Node.js', 'Learn Node.js, JavaScript, Express.js, REST APIs, MongoDB, authentication, real-time communication, security, testing, deployment, and advanced backend technologies through a structured learning pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789565756595_ctprl2u425p.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
