INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('8c56e3b7-8ae2-455a-ade6-550a3ef534a2', 'uiux-design', 'UI/UX Design', NULL, 'Learn to design intuitive, accessible, and visually engaging digital experiences through user research, design thinking, information architecture, wireframing, UI design, prototyping, testing, and design systems. Build practical skills with Figma, modern design tools, collaboration workflows, portfolio development, and professional career preparation.', '["UI/UX Design Principles & User-Centered Design","User Research, Information Architecture & Wireframing","Figma, UI Design, Prototyping & Design Systems","UX Testing, Portfolio Development & Career Preparation"]'::jsonb, 'https://marvelslice.com/uploads/1789562700985_6ovs1wtim4m.jpg', NULL, NULL, '4581e659-32d3-4592-9a3e-3506f5d51995', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '4 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T12:45:43.957906+00:00', false, 'Design Better Digital Experiences with UI/UX', 'Learn user research, wireframing, Figma, UI design, prototyping, testing, design systems, and portfolio development through a structured UI/UX learning pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789562721686_emc2kh8xqlv.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('76173129-30b2-4125-8fc0-1571b41d4df5', 'python-full-stack-development', 'Python Full Stack Development', NULL, 'Learn full-stack application development using Python, Django, React.js, SQL, REST APIs, and modern deployment technologies. Build your skills from programming fundamentals and database development through frontend engineering, backend APIs, authentication, testing, deployment, data structures, and interview preparation.', '["Python Programming & Advanced Python Development","Django, REST APIs & React.js","SQL, Database Development & API Integration","Testing, Deployment, DSA & Interview Preparation"]'::jsonb, 'https://marvelslice.com/uploads/1789563333598_k7ax830u59f.jpg', NULL, NULL, '3bd61124-499f-4929-bff1-3c46199dba18', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T12:56:23.512852+00:00', false, 'Build Modern Full Stack Applications with Python', 'Learn Python, Django, React, databases, REST APIs, authentication, testing, deployment, and DSA through a structured full-stack development pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789563354729_tg8evvy3mys.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('0b6b63a3-2b7b-46e6-8282-f5f8367d56b1', 'php-full-stack-development', 'PHP Full Stack Development', NULL, 'Learn full-stack web development using PHP, MySQL, Laravel, modern frontend technologies, REST APIs, authentication, testing, Git, and deployment. Progress from programming and web fundamentals to database-driven applications, Laravel development, API integration, security, performance optimization, and production deployment.', '["PHP Programming & Object-Oriented Development","MySQL, Database Integration & Laravel Framework","REST APIs, Authentication & Front-End Integration","Testing, Git, DevOps & Application Deployment"]'::jsonb, 'https://marvelslice.com/uploads/1789563559600_968r2w9jk2r.jpg', NULL, NULL, '3bd61124-499f-4929-bff1-3c46199dba18', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T12:59:54.551946+00:00', false, 'Build Professional Full Stack Applications with PHP', 'Learn PHP, MySQL, Laravel, REST APIs, frontend integration, authentication, security, testing, Git, and deployment through a complete full-stack development pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789563571597_ibcn6w3gq1m.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('23cc9eb3-cdde-4a11-95ee-0b718ed79979', 'react-js', 'React JS', NULL, 'Learn React JS from fundamentals to production-ready frontend development through JSX, reusable components, props, state, hooks, routing, API integration, Context API, Redux Toolkit, authentication, styling, testing, performance optimization, and deployment. Build modern and responsive web applications using a structured, practical learning path.', '["React Fundamentals, JSX & Reusable Components","Hooks, State Management & React Router","REST APIs, Context API, Redux Toolkit & Authentication","Testing, Performance Optimization & Deployment"]'::jsonb, 'https://marvelslice.com/uploads/1789563052638_92ahux128yk.jpg', NULL, NULL, 'e92c9cd6-fb33-4fbf-9c27-3c02625d50b3', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '4 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T12:51:44.739778+00:00', false, 'Build Modern Web Applications with React JS', 'Learn React, JSX, components, hooks, APIs, state management, authentication, testing, performance optimization, and deployment through a complete frontend development pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789563075447_uwkpbqwru2f.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('d3c79e1a-4c17-4d5f-b1ab-e40484ff0c64', 'front-end-developer', 'Front-End Developer', NULL, 'Build complete front-end development skills from web fundamentals and HTML5 through CSS3, Bootstrap 5, JavaScript ES6+, Git and GitHub, React.js, REST APIs, accessibility, performance optimization, and modern deployment platforms.', '["Web Fundamentals, HTML5, CSS3 & Responsive Design","Bootstrap 5, JavaScript ES6+ & Browser APIs","Git, GitHub, React.js, Hooks & API Integration","Advanced Front-End Development, Optimization & Deployment"]'::jsonb, 'https://marvelslice.com/uploads/1789566140252_ebtrudkgfx.jpg', NULL, NULL, 'e92c9cd6-fb33-4fbf-9c27-3c02625d50b3', 4.5, 0, 0, 'Talk to Advisor', 'Brochure Enquiry', '3 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T13:42:25.625144+00:00', false, 'Accelerate Your Tech Career with Front-End Developer', 'Join ambitious developers and professionals mastering high-demand engineering skills with Marvel Slice Academy.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789566052815_igygvrehb8.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('38c283bf-0124-4dad-a95a-2a1ee888fc9d', 'angular-development', 'Angular Development', NULL, 'Learn modern Angular development from the fundamentals of Angular and TypeScript through component architecture, data binding, directives, pipes, services, dependency injection, routing, forms, REST APIs, RxJS, authentication, state management, UI frameworks, testing, performance optimization, Git, and deployment.', '["Angular Fundamentals, TypeScript & Component Architecture","Data Binding, Directives, Pipes, Services & Routing","Forms, REST APIs, RxJS, Authentication & State Management","UI Frameworks, Performance, Testing, Git & Deployment"]'::jsonb, 'https://marvelslice.com/uploads/1789564629150_2sd0vapc7wg.jpg', NULL, NULL, 'e92c9cd6-fb33-4fbf-9c27-3c02625d50b3', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T13:16:20.148693+00:00', false, 'Build Modern Web Applications with Angular', 'Learn Angular, TypeScript, components, routing, forms, REST APIs, RxJS, authentication, NgRx, testing, optimization, Git, and deployment through a structured Angular development pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789564549996_q8ogub3jfac.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "video_url", "nav_item_id", "rating", "review_count", "learner_count", "cta_left", "cta_right", "duration", "mode", "status", "curriculum", "is_published", "created_at", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "start_date", "pay_now_url", "cta_left_action") VALUES ('85a7229f-cde1-48fa-a22f-16bffefac934', 'php-developer', 'PHP Developer', NULL, 'Learn PHP development from programming fundamentals through modern web application development using PHP, MySQL, Laravel, REST APIs, JavaScript, Git, and deployment technologies. Build a strong foundation in frontend development, server-side programming, database integration, authentication, API development, debugging, and application deployment.', '["Programming Fundamentals, HTML5, CSS3 & JavaScript","Core PHP, Advanced PHP & Object-Oriented Programming","MySQL, Database Integration, Laravel & REST APIs","Git, Debugging, Deployment & Production Development"]'::jsonb, 'https://marvelslice.com/uploads/1789563795561_gxkc35i5e9e.jpg', NULL, NULL, 'bc18c759-26c3-4513-89c0-4a96f36f4b48', 4.5, 0, 0, 'Talk to Agent', 'Brochure Enquiry', '6 months', 'Online', 'Active', '[]'::jsonb, true, '2026-09-16T13:03:59.806803+00:00', false, 'Build Your Career as a PHP Developer', 'Learn PHP, MySQL, Laravel, REST APIs, frontend technologies, authentication, Git, debugging, and deployment through a structured PHP development pathway.', 'Apply Now', 'https://lms.marvelslice.com/login', '', 'https://marvelslice.com/uploads/1789563815907_dn4twreeprj.jpg', NULL, 'https://lms.marvelslice.com/login', 'enquiry') ON CONFLICT DO NOTHING;

