INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('e09acfc8-b02f-4f1a-bbb6-ef3a74c126b4', '0b6b63a3-2b7b-46e6-8282-f5f8367d56b1', 'Are there any prerequisites for this course?', 'No previous PHP full-stack development experience is required. The course begins with programming and web development fundamentals before progressing into PHP, databases, Laravel, APIs, security, testing, and deployment.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('811fa38c-fd90-445b-9808-8b7aceb42940', '0b6b63a3-2b7b-46e6-8282-f5f8367d56b1', 'Will Laravel be covered in detail?', 'Yes. The Laravel module covers installation and setup, MVC architecture, routing, controllers, Blade templates, models, migrations, seeders, Eloquent ORM, validation, authentication, middleware, and file storage.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('c7204a79-ea2e-4049-bb76-bb1076fff766', '0b6b63a3-2b7b-46e6-8282-f5f8367d56b1', 'Does the course include MySQL and database integration?', 'Yes. The course covers database design, SQL commands, DDL, DML, DCL, TCL, constraints, joins, views, stored procedures, indexes, triggers, and PHP integration using PDO or MySQLi.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('4343ce83-5b7e-4b7e-aa9a-88c75fa9573e', '0b6b63a3-2b7b-46e6-8282-f5f8367d56b1', 'Does the course cover deployment and DevOps?', 'Yes. Deployment topics include Linux basics, Apache/Nginx, shared hosting, VPS deployment, Docker basics, domain and SSL configuration, cPanel deployment, and basic CI/CD concepts.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('3cc570f3-f503-49be-80c6-0f2725aec77d', '3ef4753d-d5bd-4403-89db-964daf4fa5ac', 'Are there any prerequisites for this course?', 'The uploaded syllabus does not specify formal prerequisites. The curriculum begins with Python programming and progressively introduces mathematics, statistics, data preprocessing, machine learning, deep learning, computer vision, NLP, Generative AI, LLMs, MLOps, deployment, and responsible AI.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('67599ec0-ffe3-4ffd-bebc-00fde384310b', '3ef4753d-d5bd-4403-89db-964daf4fa5ac', 'Will Python be covered for AI and Machine Learning?', 'Yes. The Python module covers Python fundamentals, data structures, functions, modules, exception handling, file handling, object-oriented programming, functional programming concepts, virtual environments, packages, NumPy, Pandas, Matplotlib, and Seaborn.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('b50edf8e-5f8a-4728-9ec1-e7a5f782a36e', '3ef4753d-d5bd-4403-89db-964daf4fa5ac', 'Does the course include Generative AI and LLMs?', 'Yes. The syllabus includes Generative AI fundamentals, LLM concepts, Transformers, attention mechanisms, prompt engineering, zero-shot and few-shot prompting, embeddings, vector databases, RAG, fine-tuning basics, AI agents, function or tool calling, LLM APIs, and AI chatbot development.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('03342c32-ae6b-4a88-a835-d70f37760ae6', '3ef4753d-d5bd-4403-89db-964daf4fa5ac', 'Does the course include deployment and MLOps?', 'Yes. The MLOps and Deployment module covers the ML project lifecycle, Git and GitHub, model serialization, Flask or FastAPI, REST APIs, Docker, ML model deployment, cloud deployment basics, MLflow, model monitoring, CI/CD for ML, and an introduction to Kubernetes.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('d6d1c90f-7c15-4cbd-bf5e-bb7b493e6e24', '23cc9eb3-cdde-4a11-95ee-0b718ed79979', 'Are there any prerequisites for this course?', 'Basic knowledge of HTML, CSS, and JavaScript is recommended because React builds on JavaScript and browser development concepts. The course begins with React fundamentals and progressively introduces more advanced application development concepts.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('1ee574c8-da11-4749-b42c-af700d0840c2', '23cc9eb3-cdde-4a11-95ee-0b718ed79979', 'Will I learn React Hooks?', 'Yes. The course covers useState, useEffect, useRef, useMemo, useCallback, useContext, and custom hooks, along with practical usage of hooks for state, side effects, references, performance, and shared application logic.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('78db9f3f-ad7d-4d32-aff1-a60aa4eb49ee', '23cc9eb3-cdde-4a11-95ee-0b718ed79979', 'Does the course cover API integration?', 'Yes. You will learn REST API fundamentals, Fetch API, Axios, GET, POST, PUT, and DELETE requests, loading states, error handling, and integration of API-driven data into React applications.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('ec5da9ab-5adf-4573-917a-92800e53c46c', '23cc9eb3-cdde-4a11-95ee-0b718ed79979', 'Does the course include deployment?', 'Yes. Deployment topics include production builds, Netlify, Vercel, GitHub Pages, and environment variables so learners understand how React applications are prepared and published.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('709d15c1-e1b5-43bc-bbff-3c762a0b6815', 'e4e63773-d434-4cbf-b927-c13eee2a14d6', 'Are there any prerequisites for this course?', 'The uploaded syllabus does not specify formal prerequisites. The learning path begins with Web Development Fundamentals and progressively introduces HTML, semantic HTML, forms, CSS, layouts, responsive design, UI components, accessibility, Git, debugging, and deployment.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('6f393f4d-c272-4a10-8afd-5a089d867102', 'e4e63773-d434-4cbf-b927-c13eee2a14d6', 'Will HTML5 be covered in detail?', 'Yes. The HTML modules cover document structure, DOCTYPE, headings, paragraphs, text formatting, comments, links, images, audio, video, lists, tables, entities, semantic elements, accessibility-friendly HTML, forms, validation, and HTML5 validation attributes.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('08fea95b-d65f-46c7-9b62-b46cc1832db6', 'e4e63773-d434-4cbf-b927-c13eee2a14d6', 'Does the course cover responsive web design?', 'Yes. Responsive Web Design covers mobile-first and desktop-first approaches, viewport concepts, media queries, breakpoints, responsive images, responsive typography, mobile navigation, tablet layouts, desktop layouts, and device testing.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('d209e669-9dc7-4c1c-b763-386adc4dfced', 'e4e63773-d434-4cbf-b927-c13eee2a14d6', 'Does the course include Git and deployment?', 'Yes. Git and GitHub Basics covers repositories, common Git commands, branches, remote repositories, push, pull, clone, and static website deployment. Website Deployment covers production preparation, optimization, SEO basics, metadata, static hosting, and domain basics.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('39835e8b-91d0-4784-ad83-be7e9b262d75', '77103a8b-5d86-4b71-8e8d-fe74ca961b77', 'Are there any prerequisites for this course?', 'The uploaded syllabus does not specify formal prerequisites. The course begins with Node.js and JavaScript fundamentals and progressively introduces backend development, databases, authentication, real-time applications, security, testing, deployment, and advanced Node.js concepts.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('4ae35adf-f87e-4c1d-90e2-a05284e5eb46', '77103a8b-5d86-4b71-8e8d-fe74ca961b77', 'Will JavaScript be covered?', 'Yes. The JavaScript Essentials module covers variables, data types, functions, arrays, objects, ES6+ features, arrow functions, destructuring, template literals, promises, and async/await.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('39b715d9-1ba0-4fdb-a91b-93cfd7244325', '77103a8b-5d86-4b71-8e8d-fe74ca961b77', 'Does the course include MongoDB?', 'Yes. Database Integration covers MongoDB basics, Mongoose, CRUD operations, schemas, models, relationships, and indexing.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('282a9b28-9fd5-432f-8f5d-1fabc069a9bc', '77103a8b-5d86-4b71-8e8d-fe74ca961b77', 'Does the course include authentication?', 'Yes. Authentication and Authorization covers bcrypt password hashing, JWT authentication, registration, login, protected routes, and role-based authorization.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('6b16d4f6-a057-4117-b365-3d21c5f6b46c', 'd4b389f5-3cd1-4008-955f-9c5898d93f04', 'Will Python be covered?', 'Yes. Python for AI covers Python basics, data types, loops, functions, object-oriented programming, file handling, NumPy, Pandas, Matplotlib, virtual environments, and pip package management.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('fcf26fd5-3a70-40fb-8b1a-1662ec872101', 'd4b389f5-3cd1-4008-955f-9c5898d93f04', 'Does the course cover RAG and vector databases?', 'Yes. The curriculum covers RAG architecture, document loading, text chunking, embeddings, vector databases, semantic search, knowledge-base integration, FAISS, ChromaDB, Pinecone, and Milvus.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('f90353a9-5304-4f8e-a4b2-766d644e2086', 'd4b389f5-3cd1-4008-955f-9c5898d93f04', 'Does the course cover AI agents?', 'Yes. The AI Agents module covers agent concepts, tool calling, multi-agent systems, autonomous workflows, and AI assistants.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('dc74a3cc-2618-4d18-b2c8-93c1d50a7378', '90c98056-68be-46be-aa04-d50b31acd8bb', 'Are there any prerequisites for this course?', 'The uploaded syllabus does not specify formal prerequisites. The course begins with programming fundamentals and Python for Data Science before progressing through statistics, SQL, data analysis, visualization, machine learning, deep learning, NLP, time series, cloud, and deployment.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('56423314-dffe-4052-94bf-1a7dbbc9de85', '90c98056-68be-46be-aa04-d50b31acd8bb', 'Will Python be covered in detail?', 'Yes. The course covers Python installation, Jupyter Notebook, VS Code, data types, strings, lists, tuples, sets, dictionaries, functions, modules, NumPy, and Pandas.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('7346aa4a-45af-4836-bd1c-b199617622e8', '90c98056-68be-46be-aa04-d50b31acd8bb', 'Does the course include Machine Learning?', 'Yes. The Machine Learning modules cover supervised and unsupervised learning, regression, classification, clustering, Decision Trees, Random Forest, KNN, SVM, and Naïve Bayes, followed by model evaluation and feature engineering.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('fefe465e-8a7e-4a37-811a-8634acbd2e3f', '90c98056-68be-46be-aa04-d50b31acd8bb', 'Does the course include deployment and cloud technologies?', 'Yes. The syllabus includes Flask/FastAPI, REST APIs, Docker, model deployment, Streamlit dashboards, Hadoop and Spark overviews, cloud concepts, AWS basics, Azure basics, Git, and GitHub.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('8770178a-91d8-443b-b740-9fa0ffecbe03', '38c283bf-0124-4dad-a95a-2a1ee888fc9d', 'Are there any prerequisites for this course?', 'The source document does not specify formal prerequisites. The curriculum begins with Angular fundamentals and TypeScript fundamentals before progressively introducing components, routing, forms, APIs, RxJS, authentication, state management, testing, and deployment.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('995798d3-9868-4119-9a81-da126d3caab7', '38c283bf-0124-4dad-a95a-2a1ee888fc9d', 'Will TypeScript be covered?', 'Yes. TypeScript Fundamentals covers variables, data types, operators, functions, arrays, objects, interfaces, classes, inheritance, access modifiers, modules, and generics.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('8a1898a8-edae-47c2-9fdf-bb2563b264a4', '38c283bf-0124-4dad-a95a-2a1ee888fc9d', 'Does the course include REST API integration?', 'Yes. The HTTP Client and REST APIs module covers HttpClient, GET, POST, PUT, DELETE, PATCH, error handling, and interceptors.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('4bd18faa-2396-42cf-9d3b-5c55d06c5459', '38c283bf-0124-4dad-a95a-2a1ee888fc9d', 'Does the course cover deployment?', 'Yes. The deployment module covers production builds, environment configuration, Firebase, Netlify, Vercel, IIS, and basic CI/CD concepts.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('d6449731-8e5d-4545-b4a5-f0838d843895', '95180125-244b-40fd-bf1c-feb7847f6547', 'Are there any prerequisites for this course?', 'The uploaded syllabus does not specify formal prerequisites. The course starts with an introduction to web design and progressively covers HTML5, CSS3, responsive design, Bootstrap, JavaScript, UI/UX, Figma, image editing, React, performance, publishing, and SEO.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('b619cb80-4547-4407-aa6c-daeb40563abf', '95180125-244b-40fd-bf1c-feb7847f6547', 'Does the course include UI/UX and Figma?', 'Yes. UI/UX covers design principles, user research basics, personas, user journeys, information architecture, wireframes, visual hierarchy, typography, color theory, spacing, design systems, accessibility, and responsive UI design. Figma covers frames, shapes, text, components, Auto Layout, constraints, variants, styles, prototyping, interactive prototypes, developer handoff, and design-to-HTML workflow.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('3459d91e-4352-449c-834b-9929332558b0', '95180125-244b-40fd-bf1c-feb7847f6547', 'Does the course include JavaScript and React?', 'Yes. JavaScript covers programming fundamentals, DOM manipulation, events, form validation, dynamic content, and basic API usage. Modern Front-End expands into ES6+, Promises, async/await, Fetch API, JSON, and API integration. React covers components, JSX, props, state, events, conditional rendering, lists, forms, Hooks, useState, useEffect, API integration, and React Router.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('b2c81fbd-92ec-45bd-a982-482a4404425a', '95180125-244b-40fd-bf1c-feb7847f6547', 'Does the course cover SEO and website publishing?', 'Yes. Website Publishing covers domains, hosting, cPanel, FTP, file management, SSL/HTTPS, deployment, Git and GitHub basics, production builds, environment variables, backups, and maintenance. SEO covers search engine basics, on-page SEO, metadata, headings, image alt text, SEO-friendly URLs, sitemap, robots.txt, mobile SEO, page speed, and Search Console basics.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('75239022-f66e-4fd6-894c-02e57fb2e282', 'd3c79e1a-4c17-4d5f-b1ab-e40484ff0c64', 'Are there any prerequisites for this course?', 'The uploaded syllabus does not specify formal prerequisites. The learning path starts with Web Fundamentals and progressively introduces HTML5, CSS3, Bootstrap, JavaScript, Git, React.js, APIs, advanced front-end concepts, and deployment.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('509c2fdf-f3c8-41e9-a022-01c4a9c4f225', 'd3c79e1a-4c17-4d5f-b1ab-e40484ff0c64', 'Will JavaScript be covered in detail?', 'Yes. The JavaScript module covers variables, data types, operators, conditions, loops, functions, arrays, objects, string methods, DOM manipulation, events, form validation, local storage, JSON, Fetch API, async/await, and Promises.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('7969e7cb-5d6c-4bb7-8f5b-7fcad6175711', 'd3c79e1a-4c17-4d5f-b1ab-e40484ff0c64', 'Does the course include React.js?', 'Yes. React.js covers JSX, components, props, state, event handling, forms, lists and keys, React Hooks, useState, useEffect, React Router, API integration, and Context API.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('ff0911f6-bcfc-43ca-9fc3-e78eba827dee', 'd3c79e1a-4c17-4d5f-b1ab-e40484ff0c64', 'Does the course cover responsive and accessible websites?', 'Yes. CSS3 includes media queries and responsive design, while Advanced Front-End covers accessibility using WCAG, responsive images, lazy loading, and cross-browser compatibility.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('ad916259-45d6-4275-8e22-1ab69f5f2170', 'd4b389f5-3cd1-4008-955f-9c5898d93f04', 'Are there any prerequisites for this course?', 'The uploaded syllabus does not specify formal prerequisites. The course begins with Artificial Intelligence fundamentals and Python before progressively introducing Generative AI, LLMs, prompt engineering, APIs, RAG, vector databases, LangChain, AI agents, application development, deployment, and security.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('41b2fd1a-752d-49d1-bbd4-25cfa5d82cc3', '85a7229f-cde1-48fa-a22f-16bffefac934', 'Are there any prerequisites for this course?', 'No previous PHP development experience is required. The course begins with programming fundamentals and frontend technologies before progressing into PHP, MySQL, Laravel, REST APIs, Git, debugging, and deployment.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('82bec75a-31a5-43d3-83fd-1de9d51b7143', '85a7229f-cde1-48fa-a22f-16bffefac934', 'Will frontend development be covered?', 'Yes. The curriculum includes HTML5, CSS3, Bootstrap 5, JavaScript, responsive design, DOM manipulation, events, ES6 features, and Fetch API fundamentals.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('ba619c3e-fda7-4e5c-be6e-3f401a8e9b3e', '85a7229f-cde1-48fa-a22f-16bffefac934', 'Does the course include Laravel?', 'Yes. Laravel covers installation, MVC architecture, routing, controllers, Blade templates, models, migrations, validation, and authentication basics.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('441f17c6-871c-414c-87d5-1e982cf55515', '85a7229f-cde1-48fa-a22f-16bffefac934', 'Does the course cover deployment?', 'Yes. The deployment module covers error handling, debugging techniques, Apache setup, shared hosting deployment, domain and SSL configuration, and Docker basics.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('6834b36a-fbcb-4b57-bf29-d6b5942cf3a9', '34d0272e-3a86-455e-93a5-f5d254e5f388', 'Are there any prerequisites for this course?', 'No previous Python development experience is required. The course begins with programming fundamentals and progressively introduces Core Python, OOP, advanced Python, databases, web frameworks, APIs, automation, testing, and deployment.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('825b5b91-f3f8-490d-8c61-27e385e21904', '34d0272e-3a86-455e-93a5-f5d254e5f388', 'Will Flask and Django both be covered?', 'The source curriculum specifies Web Framework using Flask or Django. The course introduces framework concepts including routing, templates, forms, CRUD operations, authentication, sessions, file uploads, and email integration.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('1d2b89e2-3d89-4238-9603-ccb53255d0e8', '34d0272e-3a86-455e-93a5-f5d254e5f388', 'Does the course include database development?', 'Yes. The course covers MySQL database concepts, SQL commands, DDL, DML, DCL, TCL, constraints, joins, views, stored procedures, indexes, Python MySQL connectivity, CRUD operations, transactions, error handling, and database optimization.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('e53d671a-6b0e-4443-a420-8510c77ed555', '34d0272e-3a86-455e-93a5-f5d254e5f388', 'Does the course include automation?', 'Yes. The Automation module covers file automation, Excel automation, email automation, web scraping with BeautifulSoup, and Selenium basics.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('b5682452-8f1b-4e87-9fc1-acb8c88b9fe2', 'df826b4d-7cf8-4d23-8787-77659d046dcd', 'Are there any prerequisites for this course?', 'The course starts with programming fundamentals, so prior Java experience is not required. Basic computer knowledge and an interest in software development are recommended.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('08a65719-27f6-4ab3-bc21-c59738fc1709', 'df826b4d-7cf8-4d23-8787-77659d046dcd', 'Will I receive a certificate upon completion?', 'Yes, learners who successfully complete the course requirements receive a certificate of completion.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('ebcd8421-8e0e-497d-9e5e-aba10ffe7d96', 'df826b4d-7cf8-4d23-8787-77659d046dcd', 'Is frontend development included?', 'Yes. The curriculum covers HTML5, CSS3, Bootstrap 5, JavaScript ES6+, and React.js or Angular, along with responsive UI development and API integration.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('6fd44b43-c673-4df8-af03-930a9ee29bb0', 'df826b4d-7cf8-4d23-8787-77659d046dcd', 'Does the course cover deployment and DevOps?', 'Yes. The final part of the curriculum covers Linux basics, Docker, Docker Compose, Nginx, AWS EC2 basics, CI/CD concepts, and application deployment.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('7f2bc8ed-3b1b-4fb4-8496-4f7551043e6c', 'a39cc67a-9586-4202-850a-914b5b7cf45a', 'Are there any prerequisites for this course?', 'No previous WordPress development experience is required. Basic computer knowledge and an interest in website development are recommended because the course begins with web development fundamentals.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('ac83e689-fe57-49e6-8462-97edda0992c6', 'a39cc67a-9586-4202-850a-914b5b7cf45a', 'Will PHP development be covered?', 'Yes. The course covers PHP basics, variables, functions, arrays, loops, conditional statements, WordPress PHP functions, and template tags. These concepts are then applied to custom WordPress theme development.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('704d03a5-dbd9-4ea0-9df5-936e29a66940', 'a39cc67a-9586-4202-850a-914b5b7cf45a', 'Does the course include WooCommerce?', 'Yes. The WooCommerce module covers installation, product management, categories, orders, coupons, payment gateway integration, shipping methods, and tax settings for developing e-commerce websites.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('bc053c59-a3f2-4ec1-a5dd-ff29cac3d296', 'a39cc67a-9586-4202-850a-914b5b7cf45a', 'Does the course cover website deployment?', 'Yes. Deployment topics include Git, GitHub, website migration, cPanel deployment, VPS deployment, domain configuration, SSL certificates, and ongoing website maintenance.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('8eabe320-7151-49ad-8d75-07368a8abfd1', '8c56e3b7-8ae2-455a-ade6-550a3ef534a2', 'Are there any prerequisites for this course?', 'No previous UI/UX design experience is required. Basic computer knowledge, an interest in digital products, and a willingness to explore design tools are recommended.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('281c81c9-c0af-4428-a238-0eca07d3a23d', '8c56e3b7-8ae2-455a-ade6-550a3ef534a2', 'Will I learn Figma?', 'Yes. The course provides dedicated Figma training covering the interface, frames, layouts, components, Auto Layout, variants, styles, libraries, collaboration, version history, plugins, and prototype workflows.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('4ec4025b-13fe-4db1-8fcf-07d3529ea6d0', '8c56e3b7-8ae2-455a-ade6-550a3ef534a2', 'Does the course include portfolio development?', 'Yes. Portfolio development includes case study writing, portfolio website creation, Behance, Dribbble, LinkedIn branding, and resume preparation.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('e856ae62-55ee-4df0-ba48-4b3f3acd9d8c', '8c56e3b7-8ae2-455a-ade6-550a3ef534a2', 'Does the course cover freelancing and interviews?', 'Yes. The final module covers freelancing platforms, client communication, proposal writing, pricing design projects, interview preparation, and mock interviews.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('e2b09a16-0184-42c8-913a-f841e9e54e27', '76173129-30b2-4125-8fc0-1571b41d4df5', 'Are there any prerequisites for this course?', 'No previous Python full-stack development experience is required. The course begins with programming fundamentals and progressively introduces Python, databases, frontend development, Django, REST APIs, React, testing, deployment, and other development concepts.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('09964818-f93b-4b32-8d04-9fe905bc3a07', '76173129-30b2-4125-8fc0-1571b41d4df5', 'Will both frontend and backend development be covered?', 'Yes. The frontend portion covers HTML5, CSS3, Bootstrap 5, JavaScript, and React.js, while the backend portion covers Python, Django, Django REST Framework, databases, authentication, API development, and related server-side technologies.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('b847ad7f-da32-4f24-abef-24dbb60936a0', '76173129-30b2-4125-8fc0-1571b41d4df5', 'Does the course include deployment?', 'Yes. Deployment covers Linux basics, Nginx, Gunicorn, Docker, Docker Compose, AWS EC2 basics, domain configuration, SSL certificates, and deployment using Render or Railway.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('a66bfaa2-fc99-45ce-975d-94824634e8db', '76173129-30b2-4125-8fc0-1571b41d4df5', 'Does the course include interview preparation?', 'Yes. The final module covers Python, Django, SQL, JavaScript, and React interview questions along with HR preparation, resume building, LinkedIn profile optimization, and mock interviews.', 3) ON CONFLICT DO NOTHING;

