INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('c70ea839-40a1-494b-b763-9f5d6d9e98ba', 'faqs', 'Frequently Asked Questions', 'Everything you need to know before getting started', '{"items":[{"answer":"We offer a wide range of courses including web development, data science, cloud computing, cybersecurity, and competitive exam coaching for TNPSC, UPSC, SSC, Banking, and Railway exams.","question":"What courses do you offer?"},{"answer":"We offer both online and offline (hybrid) learning options. Our online courses include live sessions and recorded content, while offline classes are conducted at our training centers.","question":"Are your courses online or offline?"},{"answer":"Yes, we provide comprehensive placement assistance including resume building, mock interviews, and job referrals. Our placement support team works closely with industry partners to connect you with the right opportunities.","question":"Do you provide placement assistance?"},{"answer":"Course durations vary depending on the program. Short-term courses range from 2-3 months, while comprehensive programs span 4-6 months. Competitive exam coaching runs up to 8-10 months.","question":"What is the duration of your courses?"},{"answer":"Yes, you will receive a verified completion certificate upon successfully finishing the course. Our certificates are recognized by industry partners.","question":"Do I get a certificate after completing a course?"},{"answer":"Absolutely! We offer free demo classes for all our courses. Simply fill out the form on our website or contact us to schedule your free demo session.","question":"Can I get a free demo before enrolling?"}]}'::jsonb, true, 10, '2026-09-17T10:37:10.478768+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('447904c3-062c-40d6-a648-a9891f4271cb', 'empowering', 'Empower Learning; Building Future.', '', '{"heading":"","description":"           At Marvel Slice, we believe that learning is the foundation for a successful future. Our mission is to empower students and aspiring professionals with the right knowledge, practical skills, and confidence to achieve their goals. Through our Software Learning and Competitive Exam Training, we create an engaging learning environment that encourages curiosity, strengthens abilities, and prepares learners to face real-world challenges. Whether you are building a career in technology or preparing for competitive examinations, Marvel Slice is committed to guiding you at every step of your journey. Learn today, grow with confidence, and build a brighter future with us."}'::jsonb, true, 4, '2026-09-17T10:37:09.470491+00:00') ON CONFLICT DO NOTHING;
