INSERT INTO public."banking_testimonials" ("id", "name", "role", "exam_name", "quote", "rating", "avatar_url", "badge_text", "is_active", "sort_order", "created_at", "updated_at", "bank_name") VALUES ('9453543f-e88d-42a4-949e-9ecfb3b30306', 'Monika Chandru', 'Scale II Manager -', 'IDBI PGDBF', 'My journey towards clearing the IDBI PGDBF P.O., examination was filled with challenges, deep learning, and moments when I had to push myself beyond my limits. One of the biggest turning points in my preparation was having attended Sundar Bro''s private mentorship classes, now readily available through Marvel SLICE platform. This achievement is not just a result for me—it is a reminder that with the right mentor, determination, and consistent hard work, every dream is achievable.', 5, 'https://marvelslice.com/uploads/1789476870374_ajxo4xxuwm.jpg', 'IDBI PO, 2021', true, 0, '2026-09-03T07:05:54.667356+00:00', '2026-09-15T12:54:32.231+00:00', 'IDBI - 2021 / SBI - 2026') ON CONFLICT DO NOTHING;
INSERT INTO public."banking_testimonials" ("id", "name", "role", "exam_name", "quote", "rating", "avatar_url", "badge_text", "is_active", "sort_order", "created_at", "updated_at", "bank_name") VALUES ('477b2578-6d8c-41e0-80fa-da512964d659', 'Athish Ragavendira C R', 'CSA / Clerk', 'IBPS Clerk', '"Marvel SLICE" is a wonderful platform, Best Wishes for Sundar Anna and team. I attended his personal mentorship classes from 2020. Anna always encouraged me to identify my strengths and work patiently on my weaknesses. Whenever I felt confused or lacked confidence, his guidance gave me the clarity and motivation to keep moving forward. His personalized approach helped me improve my speed, accuracy, time management, and overall exam strategy.', 5, 'https://marvelslice.com/uploads/1789476882013_ptdte4hbati.jpg', 'Union Bank, 2022', true, 0, '2026-09-03T07:25:56.103248+00:00', '2026-09-15T12:54:43.543+00:00', 'Union Bank - 2022') ON CONFLICT DO NOTHING;

